import * as T from './assets/vendor/three.module.js';
export function addTrainWindowReflections(body,owner){
 const panes=[];body.traverse(mesh=>{if(!mesh.isMesh||mesh.userData.trainGlass||mesh.userData.doorRecess)return;const source=mesh.material;if(!source.map)return;const key='window-reflection:'+source.uuid;let material=owner.materials.get(key);if(!material){material=new T.MeshPhysicalMaterial({color:'#a8bdc9',metalness:.65,roughness:.1,clearcoat:1,clearcoatRoughness:.06,transparent:true,opacity:.45,depthWrite:false,side:T.DoubleSide,polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-1});material.userData.trainGlass=true;material.onBeforeCompile=shader=>{shader.uniforms.glassSource={value:source.map};shader.vertexShader='varying vec3 glassPosition;varying vec3 glassNormal;varying vec2 glassUV;\n'+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\nglassPosition=position;glassNormal=normal;glassUV=uv;');shader.fragmentShader='uniform sampler2D glassSource;varying vec3 glassPosition;varying vec3 glassNormal;varying vec2 glassUV;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <clipping_planes_fragment>','#include <clipping_planes_fragment>\nif(abs(glassPosition.x)<1.05 || glassPosition.y<1.85 || glassPosition.y>3.3 || abs(glassNormal.x)<0.55)discard;vec4 originalPane=texture2D(glassSource,glassUV);if(originalPane.a>0.25 && max(originalPane.r,max(originalPane.g,originalPane.b))>0.16)discard;');};material.customProgramCacheKey=()=> 'train-window-reflection-95';owner.materials.set(key,material);}const pane=new T.Mesh(mesh.geometry,material);pane.name='side-window-reflection';pane.position.copy(mesh.position);pane.rotation.copy(mesh.rotation);pane.scale.copy(mesh.scale);pane.userData={...mesh.userData,trainGlass:true,shadowCaster:false};pane.castShadow=false;pane.renderOrder=2;panes.push([mesh.parent,pane]);});for(const [parent,pane]of panes)parent.add(pane);
}
export class TrainWindowEnvironment{
 constructor(world){this.world=world;this.elapsed=Infinity;}
 update(dt,position){this.elapsed+=Math.max(0,dt);const w=this.world,interval=w.quality==='light'?3:w.quality==='high'?.7:1.5;if(this.elapsed<interval)return;const panes=[];w.scene.traverse(o=>{if(!o.isMesh||!o.userData.trainGlass)return;for(let p=o;p;p=p.parent)if(!p.visible)return;panes.push(o);});if(!panes.length)return;
 if(!this.target){const size=w.quality==='high'?128:w.quality==='light'?32:64;this.target=new T.WebGLCubeRenderTarget(size,{generateMipmaps:true,minFilter:T.LinearMipmapLinearFilter});this.camera=new T.CubeCamera(.5,180,this.target);}
 this.elapsed=0;this.camera.position.copy(position??w.camera.position);this.camera.position.y=Math.max(this.camera.position.y,2.5);const shadows=w.renderer.shadowMap.autoUpdate,shadowUpdate=w.renderer.shadowMap.needsUpdate;w.renderer.shadowMap.autoUpdate=false;w.renderer.shadowMap.needsUpdate=false;const own=w.playerTrain?.group,ownVisible=own?.visible;if(own)own.visible=false;for(const pane of panes)pane.visible=false;try{this.camera.update(w.renderer,w.scene);}finally{if(own)own.visible=ownVisible;for(const pane of panes)pane.visible=true;w.renderer.shadowMap.autoUpdate=shadows;w.renderer.shadowMap.needsUpdate=shadowUpdate;}
 for(const pane of panes)if(pane.material.envMap!==this.target.texture){pane.material.envMap=this.target.texture;pane.material.envMapIntensity=.9;pane.material.needsUpdate=true;}
 }
 dispose(){this.target?.dispose();}
}
